            g_SpawnParticle(1, 0, &particlePosition, &particleVelocity);

            if (moby->m_Rotation.x < 0x80) {
              moby->m_Rotation.x = -((props->m_Timer - 0x5A) >> 5);
            } else {
              moby->m_Rotation.x = (props->m_Timer - 0x5A) >> 5;
            }

