        moby->m_Rotation.y = -Atan2Fast(delta.z, magnitude);
        VecAdd(&moby->m_Position, &moby->m_Position, &delta);
        VecNull(&delta);
        g_SpawnParticle(1, 0, &moby->m_Position, &delta);
